mapper.update:
update chat_app.order_carpool
departure = #{departure}, destination = #{destination}, departure_time = #{departureTime}, number_of_people = #{numberOfPeople}, remark = #{remark}, phone = #{phone}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select id, order_id, departure, destination, departure_time, create_time, update_time, number_of_people, joined_number, remark, status, stuNumber, username, phone from chat_app.order_carpool
and stuNumber = #{stuNumber}
and departure like concat('%', #{departure}, '%')
and destination like concat('%', #{destination}, '%')
and status = #{status}
order by create_time desc
